use crate::{Result,cli::Args,ttft_stats as stats,parity_benchmark::{AdapterConfig,AIPlatformAdapter}};
use serde_json::{Value,json};
use std::{collections::BTreeMap,path::Path,time::{Duration,Instant}};
pub(crate) fn runtime_inputs(path:&Path)->Result<BTreeMap<String,String>>{let file=if path.exists(){dotenvy::from_path_iter(path)?.collect::<std::result::Result<BTreeMap<_,_>,_>>()?}else{BTreeMap::new()};let value=|names:&[&str]|names.iter().find_map(|name|std::env::var(name).ok().filter(|s|!s.is_empty()).or_else(||file.get(*name).filter(|s|!s.is_empty()).cloned())).unwrap_or_default();let mut email=value(&["ASSISTANT_TTFT_EMAIL","ASSISTANT_ISOLATION_EMAIL"]);let mut password=value(&["ASSISTANT_TTFT_PASSWORD","ASSISTANT_ISOLATION_PASSWORD"]);if email.is_empty()||password.is_empty(){let mut domain=value(&["AUTH_ALLOWED_EMAIL_DOMAIN"]);if domain.is_empty(){domain="example.com".into();}let default=value(&["DEFAULT_USER_PASSWORD"]);if !default.is_empty(){if email.is_empty(){email=format!("admin@{domain}");}if password.is_empty(){password=default;}}}let mut model=value(&["ASSISTANT_TTFT_MODEL","ASSISTANT_ISOLATION_MODEL"]);if model.is_empty(){model="qwen3.7-plus".into();}if email.is_empty()||password.is_empty(){return Err("ttft_credentials_missing".into())}Ok(BTreeMap::from([("email".into(),email),("password".into(),password),("model_id".into(),model)]))}
fn read_timing(command:&[String],since:&str)->Result<Vec<String>>{let first=command.first().ok_or("timing_log_command_failed")?;let output=std::process::Command::new(first).args(&command[1..]).arg(since).output()?;if !output.status.success(){return Err("timing_log_command_failed".into())}Ok(String::from_utf8_lossy(&output.stdout).lines().map(str::to_string).collect())}
async fn reconcile(command:Option<&[String]>,since:&str,run:Option<&str>,client:Option<f64>)->Value{let Some(command)=command else{return json!({"status":"not_collected"})};let Some(run)=run else{return json!({"status":"unmatched"})};let mut seen=BTreeMap::new();let harvest=|seen:&mut BTreeMap<String,Value>|{if let Ok(lines)=read_timing(command,since){for line in lines{if let Some(record)=stats::timing_line(&line){if record["run_id_sha256"]==run{seen.insert(record["call_id"].as_str().unwrap().into(),record);}}}}};for _ in 0..2{harvest(&mut seen);if !seen.is_empty(){break}tokio::time::sleep(Duration::from_millis(500)).await;}if seen.is_empty(){return json!({"status":"missing"})}tokio::time::sleep(Duration::from_millis(500)).await;harvest(&mut seen);if seen.len()>1{return json!({"status":"multi_call_excluded","call_count":seen.len()})}stats::reconcile(seen.values().next().unwrap(),client)}
pub(crate) fn atomic_report(path:&Path,value:&Value)->Result<()> {
 let parent=path.parent().filter(|p|!p.as_os_str().is_empty()).unwrap_or(Path::new("."));
 std::fs::create_dir_all(parent)?;
 if std::fs::symlink_metadata(path).is_ok_and(|m|m.file_type().is_symlink()||!m.is_file()){return Err("report destination must be a regular file".into())}
 let bytes=format!("{}\n",serde_json::to_string_pretty(value)?);
 let mut file=tempfile::NamedTempFile::new_in(parent)?;
 #[cfg(unix)]{use std::os::unix::fs::PermissionsExt;file.as_file().set_permissions(std::fs::Permissions::from_mode(0o600))?;}
 use std::io::Write;
 file.write_all(bytes.as_bytes())?;file.as_file().sync_all()?;
 file.persist(path).map_err(|e|e.error)?;
 Ok(())
}
fn values(trials:&[&Value],key:&str)->Vec<f64>{trials.iter().filter_map(|t|t[key].as_f64()).collect()}
pub fn summarize(results:&[Value],model:&str,thinking:&str,prompt:&str,trials:usize,warmup:usize,p50_ceiling:f64,p95_ceiling:f64,reader:bool,wall:f64,commit:&str)->Value{let successful=results.iter().filter(|t|t["success"]==true).collect::<Vec<_>>();let gate=successful.iter().copied().filter(|t|t["ordinal"].as_u64().unwrap_or(0)>warmup as u64).collect::<Vec<_>>();let mut metrics=json!({});for key in ["first_event_seconds","first_thinking_seconds","ttft_seconds","first_text_seconds","thinking_to_text_seconds","total_seconds"]{metrics[key]=stats::metric_summary(&values(&gate,key));}let ttft=values(&gate,"ttft_seconds");let reconciled=gate.iter().filter_map(|t|{let r=&t["timing_reconciliation"];["ok","tolerance_exceeded"].contains(&r["status"].as_str().unwrap_or("")).then_some(r)}).collect::<Vec<_>>();for key in stats::COMPONENTS{metrics[key]=stats::metric_summary(&reconciled.iter().filter_map(|r|r["server"][key].as_f64()).collect::<Vec<_>>());}let residuals=reconciled.iter().filter_map(|r|r["residual_seconds"].as_f64().map(f64::abs)).collect::<Vec<_>>();let mut counts=json!({});for status in ["ok","tolerance_exceeded","identity_violation","multi_call_excluded","missing","incomplete","unmatched","not_collected"]{counts[status]=json!(gate.iter().filter(|t|t["timing_reconciliation"]["status"]==status).count());}let passed=successful.len()==trials&&gate.len()==trials-warmup&&metrics["ttft_seconds"]["p50"].as_f64().is_some_and(|v|v<=p50_ceiling)&&metrics["ttft_seconds"]["p95"].as_f64().is_some_and(|v|v<=p95_ceiling);let certification=stats::certification(results,reader,gate.len(),passed);let prompt_hash=crate::canonical::sha256(prompt.as_bytes());json!({"schema_version":"assistant-ttft-benchmark/v3","ttft_definition":"first_user_visible_thinking_or_text_token","model_id":model,"thinking_level":thinking,"thinking_required":true,"execution_profile":"safe","memory_mode":"off","skills_enabled":false,"prompt_sha256":prompt_hash,"prompt_chars":prompt.chars().count(),"trial_count":trials,"successful_trials":successful.len(),"gate_trials":gate.len(),"failure_count":trials-successful.len(),"p50_ceiling_seconds":p50_ceiling,"p95_ceiling_seconds":p95_ceiling,"passed":passed,"recordable":certification["recordable"],"statistical_policy":{"warmup_trials":warmup,"min_recordable_gate_set_trials":100,"percentile_method":"nearest-rank","ttft_iqr_seconds":stats::iqr(&ttft),"ttft_p50_ci95_bootstrap":stats::bootstrap(&ttft,0.50),"ttft_p95_ci95_bootstrap":stats::bootstrap(&ttft,0.95),"bootstrap_iterations":2000,"bootstrap_seed":0,"client_clock_source":"std::time::Instant (adapter process)","server_clock_source":"monotonic clock (gateway process, single worker)"},"configuration_fingerprint":{"git_commit":commit,"git_commit_scope":"client-side operator checkout only; the running gateway stack's identity is pinned separately by deploy/runbooks/platform-plane-restructure/rollback-bundle.json and the hot-update provenance recorded in loop-state evidence","model_id":model,"thinking_level":thinking,"temperature":0.0,"max_tokens":256,"prompt_sha256":prompt_hash},"metrics":metrics,"timing_reconciliation":{"policy":{"server_timing_schema":"ppr-timing/v1","join":"sha256(run_id) against client run_started","pass_rule":"G3/v2 (user-authorized 2026-08-28): every trial needs a collected identity-clean reconciliation (exclusions fail the report); the client lower bound holds per trial; the residual upper bound is certified at p99 <= 0.25 with a hard per-trial defect ceiling <= 0.5; v1's per-trial 0.200 floor stays as informational status; and recordable additionally requires a gate-set of at least 100 trials (G5)","identity_tolerance_seconds":0.005,"client_lower_bound_seconds":0.010,"residual_abs_seconds":0.200,"residual_relative":0.05,"attribution_caveat":"provider token pacing after the first upstream frame is attributed to local_projection_seconds by definition; provider_wait is comparable only at single-stream load (downstream backpressure stalls the generator inside the provider-wait window)","residual_inventory":"client<->gateway transport, gateway pre-stream auth/session/run-creation, the agent-runtime container hop including Rust-side event processing and persistence, and client parse time","survivorship":"timing lines exist only for completed model calls; failed or aborted calls never enter the component distributions (the gate set also requires all-trial success)"},"field_scope":"status_counts and gate_set_max_abs_residual_seconds cover the gate-set only (warm-ups excluded); the all_trials_* fields are the G3/v2 certification inputs and include every trial","status_counts":counts,"gate_set_max_abs_residual_seconds":residuals.into_iter().reduce(f64::max).map(|v|(v*1e6).round_ties_even()/1e6),"gate_set_meets_recordable_min":certification["gate_set_meets_recordable_min"],"all_trials_abs_residual_p99_seconds":certification["all_trials_abs_residual_p99_seconds"],"all_trials_abs_residual_max_seconds":certification["all_trials_abs_residual_max_seconds"],"certification_bounds":{"rule":"g3/v2","residual_p99_seconds":0.250,"residual_max_seconds":0.500,"client_lower_bound_seconds":0.010},"reconciliation_passed":certification["reconciliation_passed"]},"trials":results,"wall_seconds":(wall*1e6).round_ties_even()/1e6})}
pub async fn run(args:Args)->Result<(Value,i32)>{args.reject_unknown(&["env-file","gateway-base-url","output","prompt","trials","thinking-level","p50-ceiling-seconds","p95-ceiling-seconds","warmup-trials","timing-log-command"])?;if !args.positional.is_empty(){return Err("unexpected positional argument".into())}let output=Path::new(args.required("output")?);let trials:usize=args.number("trials",10)?;let warmup:usize=args.number("warmup-trials",2)?;if !(1..=200).contains(&trials){return Err("ttft_trials_out_of_range".into())}if warmup>=trials{return Err("ttft_warmup_out_of_range".into())}let thinking=args.get("thinking-level","low");if !["low","medium","high"].contains(&thinking){return Err("ttft_thinking_must_be_enabled".into())}if output.exists(){return Err("ttft_output_exists".into())}let runtime=runtime_inputs(Path::new(args.required("env-file")?))?;let ids=(1..=trials).map(|i|(i,format!("ttft.{i}.{}",uuid::Uuid::new_v4().simple()))).collect::<BTreeMap<_,_>>();let config=AdapterConfig{gateway_base_url:args.get("gateway-base-url","http://127.0.0.1:8080/api/v1").into(),email:runtime["email"].clone(),password:runtime["password"].clone(),model_id:runtime["model_id"].clone(),temperature:0.,max_tokens:256,thinking_level:thinking.into(),execution_profile:"safe".into(),max_approval_rounds:1,task_output_formats:ids.values().map(|id|(id.clone(),"text".into())).collect()};let mut adapter=AIPlatformAdapter::new(config).await?.with_runtime_model_echo(false);let command=shell_words::split(args.get("timing-log-command",""))?;let reader=(!command.is_empty()).then_some(command.as_slice());let prompt=args.get("prompt","只回答数字：2+2等于多少？");let mut results=vec![];let start=Instant::now();for ordinal in 1..=trials{let id=&ids[&ordinal];let since=chrono::Utc::now().to_rfc3339();let outcome=async{adapter.start_task(id).await?;adapter.run_turn(id,prompt).await}.await;match outcome{Ok(result)=>{let phase=result.metadata["timing"]["phases"].as_array().and_then(|a|a.first());let events=result.metadata["event_types"].as_array();if phase.is_none()||events.is_none(){results.push(json!({"ordinal":ordinal,"success":false,"terminal_status":"infrastructure_error","reason":"malformed adapter timing receipt"}));continue}let phase=phase.unwrap();let thinking_observed=events.unwrap().iter().any(|v|v=="thinking_start"||v=="thinking_delta");let success=result.terminal_status=="succeeded"&&!result.text.is_empty()&&thinking_observed;let timing=&result.metadata["timing"];let usage=&result.metadata["usage"];let mut trial=json!({"ordinal":ordinal,"success":success,"terminal_status":result.terminal_status,"thinking_observed":thinking_observed,"first_event_seconds":phase["first_event_seconds"],"first_thinking_seconds":phase["first_thinking_seconds"],"ttft_seconds":timing["ttft_seconds"],"first_text_seconds":timing["first_text_seconds"],"thinking_to_text_seconds":phase["thinking_to_text_seconds"],"total_seconds":result.duration_seconds,"input_tokens":usage["input_tokens"],"cached_input_tokens":usage["cached_input_tokens"],"output_tokens":usage["output_tokens"]});if success{let run=result.metadata["lifecycle_events"].as_array().into_iter().flatten().find(|e|e["event_type"]=="run_started").and_then(|e|e["run_id_sha256"].as_str()).filter(|s|!s.is_empty());trial["timing_reconciliation"]=reconcile(reader,&since,run,timing["ttft_seconds"].as_f64()).await;if trial["timing_reconciliation"]["server"].get("model").is_some_and(|v|!v.is_null()&&v!=&runtime["model_id"]){trial["success"]=json!(false);trial["terminal_status"]=json!("infrastructure_error");trial["reason"]=json!("gateway_runtime_model_mismatch");}}results.push(trial);},Err(error)=>results.push(json!({"ordinal":ordinal,"success":false,"terminal_status":"infrastructure_error","reason":error.to_string()}))}}
 let commit=std::process::Command::new("git").args(["rev-parse","HEAD"]).output().ok().filter(|o|o.status.success()).map(|o|String::from_utf8_lossy(&o.stdout).trim().to_string()).filter(|s|!s.is_empty()).unwrap_or_else(||"unknown".into());let report=summarize(&results,&runtime["model_id"],thinking,prompt,trials,warmup,args.number("p50-ceiling-seconds",4.)?,args.number("p95-ceiling-seconds",5.)?,reader.is_some(),start.elapsed().as_secs_f64(),&commit);atomic_report(output,&report)?;let summary=json!({"passed":report["passed"],"recordable":report["recordable"],"successful_trials":report["successful_trials"],"ttft":report["metrics"]["ttft_seconds"],"local_overhead_p95":report["metrics"]["local_overhead_seconds"]["p95"],"provider_wait_p95":report["metrics"]["provider_wait_seconds"]["p95"],"reconciliation_passed":report["timing_reconciliation"]["reconciliation_passed"],"reconciliation_statuses":report["timing_reconciliation"]["status_counts"]});let code=if report["recordable"]==true{0}else{1};Ok((summary,code))}
pub fn configuration_fingerprint()->String{std::process::Command::new("git").args(["rev-parse","HEAD"]).output().ok().filter(|o|o.status.success()).map(|o|String::from_utf8_lossy(&o.stdout).trim().to_string()).filter(|s|!s.is_empty()).unwrap_or_else(||"unknown".into())}
#[cfg(test)]mod writer_tests {
 use super::*;
 #[test]fn report_replaces_existing_with_private_inode(){let dir=tempfile::tempdir().unwrap();let path=dir.path().join("report.json");std::fs::write(&path,"old").unwrap();atomic_report(&path,&json!({"passed":false})).unwrap();assert_eq!(crate::strict_json::parse(&std::fs::read(&path).unwrap()).unwrap(),json!({"passed":false}));#[cfg(unix)]{use std::os::unix::fs::PermissionsExt;assert_eq!(std::fs::metadata(path).unwrap().permissions().mode()&0o777,0o600);}}
 #[cfg(unix)]#[test]fn report_rejects_symlink_without_touching_target(){let dir=tempfile::tempdir().unwrap();let target=dir.path().join("target");let path=dir.path().join("report");std::fs::write(&target,"unchanged").unwrap();std::os::unix::fs::symlink(&target,&path).unwrap();assert!(atomic_report(&path,&json!({})).is_err());assert_eq!(std::fs::read_to_string(target).unwrap(),"unchanged");}
}
